"""
make_quiz_L3.py -- quiz bank of Lecture 3 (EN + RO) -> assets/quizzes/l3.js; numbers only from L3_numbers.json.
Run:  python3 lectures/L3/make_quiz_L3.py
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, os.path.join(HERE, "..", "L1"))
from quizgen import Bank  # noqa: E402

b = Bank(3, os.path.join(HERE, "L3_numbers.json"), "Regularisation and generalisation")
q, E, R, g = b.q, b.E, b.R, b.g

q(2, ("Generalisation gap", "What is the generalisation gap of a trained model?",
      ["The difference between training and validation accuracy of two models", "The number of parameters minus the number of observations",
       "The expected loss on new data minus the loss on the training data", "The gap between precision and recall"],
      "$R(\\hat f)-\\hat R_n(\\hat f)$: the training loss is optimistic because the model was fitted to those data; regularisation aims to shrink the gap while keeping $R$ low.",
      "The gap compares the same model on seen and unseen data; it is what overfitting makes large."),
  ("Diferența de generalizare", "Ce este diferența de generalizare a unui model antrenat?",
   ["Diferența dintre acuratețea de antrenare și cea de validare a două modele", "Numărul de parametri minus numărul de observații",
    "Pierderea așteptată pe date noi minus pierderea pe datele de antrenare", "Diferența dintre precizie și sensibilitate"],
   "$R(\\hat f)-\\hat R_n(\\hat f)$: pierderea de antrenare este optimistă pentru că modelul a fost estimat pe acele date; regularizarea urmărește să reducă diferența păstrînd $R$ mic.",
   "Diferența compară același model pe date văzute și nevăzute; supraînvățarea o face mare."))
q(0, ("Reading the curves", f"An MLP 256-256 on 600 German applicants has its lowest validation loss at epoch {E('overfit.best_ep', 'd')} ({E('overfit.val_min', '.3f')}) and {E('overfit.val_last', '.3f')} after {E('overfit.epochs', 'd')} epochs, with training loss near zero. Diagnosis?",
      ["Overfitting: the network memorises the training applicants", "Underfitting: the network is too small", "The learning rate is too small", "The validation set is too large"],
      "A falling training loss with a rising validation loss is the signature of overfitting; keep the best-epoch weights and regularise.",
      "Underfitting would show high training loss as well; here the training loss is almost zero, so the model is too flexible for the data."),
  ("Citirea curbelor", f"Un MLP 256-256 pe 600 de solicitanți germani are pierderea de validare minimă la epoca {R('overfit.best_ep', 'd')} ({R('overfit.val_min', '.3f')}) și {R('overfit.val_last', '.3f')} după {R('overfit.epochs', 'd')} de epoci, cu pierderea de antrenare aproape zero. Diagnosticul?",
   ["Supraînvățare: rețeaua memorează solicitanții de antrenare", "Subînvățare: rețeaua este prea mică", "Rata de învățare este prea mică", "Setul de validare este prea mare"],
   "O pierdere de antrenare care scade și una de validare care crește sînt semnătura supraînvățării; păstrați ponderile epocii celei mai bune și regularizați.",
   "Subînvățarea ar arăta și o pierdere de antrenare mare; aici pierderea de antrenare este aproape zero, deci modelul este prea flexibil pentru date."))
q(3, ("Bias-variance", "In $\\mathbb E(y-\\hat f)^2=\\text{bias}^2+\\operatorname{Var}(\\hat f)+\\sigma^2$, which term can no model reduce?",
      ["The squared bias", "The variance of the estimator", "None: all terms can be reduced to zero", "The noise variance $\\sigma^2$"],
      "$\\sigma^2$ is the variance of $\\varepsilon$ in $y=f(x)+\\varepsilon$: it is irreducible; regularisation trades bias against variance.",
      "Bias and variance depend on the model and the data; the noise is a property of the outcome itself."),
  ("Deplasare și varianță", "În $\\mathbb E(y-\\hat f)^2=\\text{deplasare}^2+\\operatorname{Var}(\\hat f)+\\sigma^2$, ce termen nu poate fi redus de niciun model?",
   ["Pătratul deplasării", "Varianța estimatorului", "Niciunul: toți termenii pot fi aduși la zero", "Varianța zgomotului $\\sigma^2$"],
   "$\\sigma^2$ este varianța lui $\\varepsilon$ din $y=f(x)+\\varepsilon$: este ireductibilă; regularizarea echilibrează deplasarea și varianța.",
   "Deplasarea și varianța depind de model și de date; zgomotul este o proprietate a rezultatului însuși."))
q(1, ("Double descent", f"With $n={E('dd.n', 'd')}$ training block groups and $p$ random ReLU features, where is the test MSE largest?",
      ["At the smallest $p$", "Near $p=n$, the interpolation threshold", "At the largest $p$", "It decreases monotonically with $p$"],
      f"At $p=n$ the minimum-norm fit interpolates the training data with huge weights; the median test MSE peaks at $p=${E('dd.peak_p', 'd')} and falls again to {E('dd.big_mse', '.3f')} at $p=${E('dd.big_p', ',d')}.",
      "Past the threshold, the minimum-norm solution among many interpolating fits is smoother, so the test error falls again: the classical U-curve is not the whole story."),
  ("Dubla coborîre", f"Cu $n={R('dd.n', 'd')}$ grupuri de antrenare și $p$ caracteristici ReLU aleatoare, unde este cea mai mare MSE pe test?",
   ["La cel mai mic $p$", "Aproape de $p=n$, pragul de interpolare", "La cel mai mare $p$", "Scade monoton cu $p$"],
   f"La $p=n$, soluția de normă minimă interpolează datele de antrenare cu ponderi uriașe; MSE mediană pe test are vîrful la $p=${R('dd.peak_p', 'd')} și scade din nou la {R('dd.big_mse', '.3f')} pentru $p=${R('dd.big_p', ',d')}.",
   "După prag, soluția de normă minimă dintre multele soluții care interpolează este mai netedă, deci eroarea pe test scade din nou: curba clasică în U nu spune totul."))
q(2, ("Weight decay update", "With an L2 penalty $\\frac\\lambda2\\|\\mathbf w\\|^2$, what does one SGD step do to the weights?",
      ["Adds $\\lambda$ to every weight", "Sets small weights to zero", "Multiplies them by $(1-\\eta\\lambda)$ before the gradient step", "Nothing: the penalty only changes the loss value"],
      "$\\mathbf w-\\eta\\nabla(\\mathcal L+\\tfrac\\lambda2\\|\\mathbf w\\|^2)=(1-\\eta\\lambda)\\mathbf w-\\eta\\nabla\\mathcal L$: hence the name weight decay.",
      "Setting weights exactly to zero is the effect of an L1 penalty; L2 shrinks all weights proportionally."),
  ("Actualizarea cu penalizare", "Cu o penalizare L2 $\\frac\\lambda2\\|\\mathbf w\\|^2$, ce face un pas SGD asupra ponderilor?",
   ["Adaugă $\\lambda$ la fiecare pondere", "Aduce ponderile mici la zero", "Le înmulțește cu $(1-\\eta\\lambda)$ înainte de pasul de gradient", "Nimic: penalizarea schimbă doar valoarea pierderii"],
   "$\\mathbf w-\\eta\\nabla(\\mathcal L+\\tfrac\\lambda2\\|\\mathbf w\\|^2)=(1-\\eta\\lambda)\\mathbf w-\\eta\\nabla\\mathcal L$: de aici numele de penalizare a ponderilor (weight decay).",
   "Aducerea exactă a ponderilor la zero este efectul penalizării L1; L2 micșorează toate ponderile proporțional."))
q(0, ("Bayesian view", "An L2 penalty corresponds to which prior on the weights in a maximum a posteriori estimate?",
      ["A Gaussian prior centred at zero", "A uniform prior", "A Laplace prior", "No prior at all"],
      "$-\\log p(\\mathbf w)=\\frac\\lambda2\\|\\mathbf w\\|^2+$const for $\\mathbf w\\sim N(\\mathbf 0,\\lambda^{-1}\\mathbf I)$, so the MAP estimate minimises the penalised loss.",
      "A Laplace prior gives the L1 penalty; a uniform prior adds nothing to the loss."),
  ("Interpretarea bayesiană", "Cărei distribuții a priori pe ponderi îi corespunde penalizarea L2 într-o estimare maximum a posteriori?",
   ["O distribuție gaussiană centrată în zero", "O distribuție uniformă", "O distribuție Laplace", "Niciunei distribuții a priori"],
   "$-\\log p(\\mathbf w)=\\frac\\lambda2\\|\\mathbf w\\|^2+$const pentru $\\mathbf w\\sim N(\\mathbf 0,\\lambda^{-1}\\mathbf I)$, deci estimarea MAP minimizează pierderea penalizată.",
   "O distribuție Laplace dă penalizarea L1; o distribuție uniformă nu adaugă nimic la pierdere."))
q(3, ("L1 sparsity", f"With an L1 penalty, {E('l1l2.share_small_l1_pct', '.1f')} % of the first-layer weights are below 0.01 in absolute value, against {E('l1l2.share_small_l2_pct', '.1f')} % with L2. Why?",
      ["L1 uses a larger learning rate", "L2 cannot be used with ReLU", "L1 penalises large weights more than L2",
       "The L1 penalty has a kink at zero: its soft-thresholding step sets small weights exactly to zero"],
      "The proximal step $w\\leftarrow\\operatorname{sign}(u)\\max(|u|-\\eta\\lambda,0)$ maps every $|u|\\le\\eta\\lambda$ to exactly zero.",
      "L2 penalises large weights more strongly and only shrinks them; the corner of the L1 ball on the axes is what creates exact zeros."),
  ("Raritatea cu L1", f"Cu penalizarea L1, {R('l1l2.share_small_l1_pct', '.1f')} % dintre ponderile primului strat sînt sub 0,01 în valoare absolută, față de {R('l1l2.share_small_l2_pct', '.1f')} % cu L2. De ce?",
   ["L1 folosește o rată de învățare mai mare", "L2 nu poate fi folosită cu ReLU", "L1 penalizează ponderile mari mai mult decît L2",
    "Penalizarea L1 are un unghi în zero: pasul ei de prag moale aduce ponderile mici exact la zero"],
   "Pasul proximal $w\\leftarrow\\operatorname{sign}(u)\\max(|u|-\\eta\\lambda,0)$ trimite orice $|u|\\le\\eta\\lambda$ exact în zero.",
   "L2 penalizează mai puternic ponderile mari și doar le micșorează; colțul bilei L1 de pe axe creează zerourile exacte."))
q(1, ("AdamW", "Why is an L2 term in the loss not the same as weight decay when training with Adam?",
      ["Adam ignores the loss", "Adam divides the L2 gradient by $\\sqrt{\\hat v}$, so weights with large gradients are barely decayed; AdamW applies the decay directly",
       "Adam has no learning rate", "AdamW uses dropout"],
      "Decoupling the decay, $\\mathbf w\\leftarrow(1-\\eta\\lambda)\\mathbf w$, restores a uniform shrinkage (Loshchilov and Hutter, 2019).",
      "With plain SGD both coincide; the adaptive rescaling of Adam is what breaks the equivalence."),
  ("AdamW", "De ce un termen L2 în pierdere nu este același lucru cu penalizarea ponderilor la antrenarea cu Adam?",
   ["Adam ignoră pierderea", "Adam împarte gradientul termenului L2 la $\\sqrt{\\hat v}$, deci ponderile cu gradienți mari aproape nu se micșorează; AdamW aplică direct micșorarea",
    "Adam nu are rată de învățare", "AdamW folosește dropout"],
   "Decuplarea, $\\mathbf w\\leftarrow(1-\\eta\\lambda)\\mathbf w$, reface o micșorare uniformă (Loshchilov și Hutter, 2019).",
   "Cu SGD simplu cele două coincid; rescalarea adaptivă din Adam strică echivalența."))
q(2, ("Small data", f"On German credit the MLP 256-256 reaches AUC {E('cv.auc_none', '.3f')} without regularisation and at best {E('cv.auc_best_p', '.3f')} with dropout, while logistic regression reaches {E('cv.auc_logit', '.3f')}. What is the lesson?",
      ["Dropout is useless", "Neural networks never work for credit", "On very small data a simpler model beats a large regularised one",
       "Logistic regression overfits less because it uses dropout"],
      "Regularisation shrinks the weights (norm from {0} to {1} for $\\lambda$ from 0 to 3) but cannot create information that 600 applicants do not contain.".format(E('wd.0.norm', '.1f'), E('wd.3.norm', '.1f')),
      "Penalties and dropout reduce variance; with so little data, a model with few parameters is the stronger form of regularisation."),
  ("Date puține", f"Pe German credit, MLP 256-256 ajunge la AUC {R('cv.auc_none', '.3f')} fără regularizare și cel mult {R('cv.auc_best_p', '.3f')} cu dropout, iar regresia logistică la {R('cv.auc_logit', '.3f')}. Care este lecția?",
   ["Dropout este inutil", "Rețelele neuronale nu funcționează niciodată pentru credit", "Pe date foarte puține, un model mai simplu depășește unul mare regularizat",
    "Regresia logistică supra-ajustează mai puțin pentru că folosește dropout"],
   "Regularizarea micșorează ponderile (norma de la {0} la {1} pentru $\\lambda$ de la 0 la 3), dar nu poate crea informație pe care 600 de solicitanți nu o conțin.".format(R('wd.0.norm', '.1f'), R('wd.3.norm', '.1f')),
   "Penalizările și dropout reduc varianța; cu atît de puține date, un model cu puțini parametri este forma mai puternică de regularizare."))
q(3, ("Inverted dropout", "In inverted dropout with rate $p$, why are the kept activations divided by $1-p$ during training?",
      ["To speed up training", "To make the network sparse", "To regularise the output layer", "To keep the expected activation unchanged, so nothing must be rescaled at test time"],
      "$\\mathbb E[m_jh_j/(1-p)]=h_j$ when $m_j\\sim$ Bernoulli$(1-p)$; at test time the full network is used as is.",
      "The division is a scaling correction, not an extra penalty; without it the test-time activations would be too large."),
  ("Dropout inversat", "În dropout-ul inversat cu rata $p$, de ce sînt împărțite activările păstrate la $1-p$ în timpul antrenării?",
   ["Pentru a accelera antrenarea", "Pentru a face rețeaua rară", "Pentru a regulariza stratul de ieșire", "Pentru a păstra neschimbată activarea medie, astfel încît la testare nu mai trebuie rescalat nimic"],
   "$\\mathbb E[m_jh_j/(1-p)]=h_j$ cînd $m_j\\sim$ Bernoulli$(1-p)$; la testare se folosește rețeaua completă, ca atare.",
   "Împărțirea este o corecție de scară, nu o penalizare suplimentară; fără ea, activările de la testare ar fi prea mari."))
q(0, ("Dropout as ensemble", "Why is dropout often described as training an ensemble?",
      ["Each mini-batch trains a different thinned sub-network, and all of them share weights; the full network at test time approximates their average",
       "It trains several separate networks with different data", "It averages the predictions of several optimisers", "It uses bagging of the training data"],
      "With $H$ droppable units there are $2^H$ possible sub-networks; weight sharing makes training them together cheap (Srivastava et al., 2014).",
      "Dropout does not resample the data or train separate models; it samples masks over one shared set of weights."),
  ("Dropout ca ansamblu", "De ce este descris adesea dropout ca antrenarea unui ansamblu?",
   ["Fiecare mini-lot antrenează o altă subrețea subțiată, toate cu ponderi comune; la testare, rețeaua completă aproximează media lor",
    "Antrenează mai multe rețele separate pe date diferite", "Face media predicțiilor mai multor optimizatori", "Folosește bagging pe datele de antrenare"],
   "Cu $H$ neuroni care pot fi opriți există $2^H$ subrețele posibile; ponderile comune fac antrenarea lor împreună ieftină (Srivastava et al., 2014).",
   "Dropout nu reeșantionează datele și nu antrenează modele separate; extrage măști peste un singur set comun de ponderi."))
q(1, ("Forgetting eval()", "What happens if a PyTorch model with dropout and batch norm scores customers without calling `model.eval()`?",
      ["Nothing changes", "Predictions become random (dropout stays on) and depend on the batch (batch statistics are used)",
       "The model trains on the test data", "The model becomes faster"],
      "`model.eval()` switches dropout off and makes batch norm use its running averages; in training mode both inject noise.",
      "Evaluation mode does not freeze gradients by itself; it changes the behaviour of dropout and batch norm layers."),
  ("Uitarea lui eval()", "Ce se întîmplă dacă un model PyTorch cu dropout și normalizare pe loturi scorează clienți fără apelul `model.eval()`?",
   ["Nu se schimbă nimic", "Predicțiile devin aleatoare (dropout rămîne activ) și depind de lot (se folosesc statisticile lotului)",
    "Modelul se antrenează pe datele de test", "Modelul devine mai rapid"],
   "`model.eval()` dezactivează dropout și face ca normalizarea pe loturi să folosească mediile mobile; în modul de antrenare, ambele adaugă zgomot.",
   "Modul de evaluare nu îngheață singur gradienții; schimbă comportamentul straturilor dropout și de normalizare pe loturi."))
q(2, ("Early stopping", f"On the fraud data the validation loss is lowest at epoch {E('es.best_ep', 'd')}; with patience {E('es.patience', 'd')} training stops at epoch {E('es.stop_ep', 'd')}. Which weights are used?",
      [f"Those of epoch {E('es.stop_ep', 'd')}", "Those of the last epoch that was planned", f"Those of epoch {E('es.best_ep', 'd')}, saved when the validation loss was lowest", "An average of all epochs"],
      "Early stopping keeps a copy of the best weights and restores them; the patience only decides when to stop looking.",
      "The weights at the stopping epoch have already overfitted for the whole patience window."),
  ("Oprirea timpurie", f"La datele despre fraude, pierderea de validare este minimă la epoca {R('es.best_ep', 'd')}; cu răbdarea {R('es.patience', 'd')}, antrenarea se oprește la epoca {R('es.stop_ep', 'd')}. Ce ponderi se folosesc?",
   [f"Cele din epoca {R('es.stop_ep', 'd')}", "Cele din ultima epocă planificată", f"Cele din epoca {R('es.best_ep', 'd')}, salvate cînd pierderea de validare era minimă", "O medie a tuturor epocilor"],
   "Oprirea timpurie păstrează o copie a celor mai bune ponderi și le restaurează; răbdarea decide doar cînd ne oprim din căutare.",
   "Ponderile din epoca de oprire au supra-ajustat deja pe toată fereastra de răbdare."))
q(3, ("Early stopping as L2", "Near a quadratic minimum, stopping gradient descent after $t$ steps of size $\\eta$ acts like an L2 penalty of strength about",
      ["$\\eta t$", "$t/\\eta$", "$\\eta^2 t$", "$1/(\\eta t)$"],
      "Along eigen-direction $k$, $1-(1-\\eta h_k)^t\\approx h_k/(h_k+\\lambda)$ when $\\lambda\\approx1/(\\eta t)$: fewer steps mean a stronger penalty.",
      "Training longer lets small-curvature directions grow, exactly what a weaker L2 penalty would allow."),
  ("Oprirea timpurie ca L2", "Lîngă un minim pătratic, oprirea coborîrii pe gradient după $t$ pași de mărime $\\eta$ acționează ca o penalizare L2 de intensitate aproximativ",
   ["$\\eta t$", "$t/\\eta$", "$\\eta^2 t$", "$1/(\\eta t)$"],
   "Pe direcția proprie $k$, $1-(1-\\eta h_k)^t\\approx h_k/(h_k+\\lambda)$ cînd $\\lambda\\approx1/(\\eta t)$: mai puțini pași înseamnă o penalizare mai puternică.",
   "O antrenare mai lungă permite direcțiilor cu curbură mică să crească, exact ce ar permite o penalizare L2 mai slabă."))
q(0, ("Batch norm", f"In a 6-layer MLP trained with SGD at $\\eta=0.1$, {E('bn.plain_01.diverged', 'd')} of 3 seeds diverge without batch norm, while with batch norm the best validation MSE is {E('bn.bn_01.val_best', '.3f')}. What does batch norm mainly provide?",
      ["Stable training at larger learning rates, by keeping pre-activations centred and scaled", "A guaranteed lower test error", "Fewer parameters", "A replacement for the validation set"],
      "Normalising each unit over the mini-batch smooths the loss landscape (Ioffe and Szegedy, 2015); its regularising effect is a side benefit.",
      "In this experiment batch norm made training possible at the high rate, but its final validation error fluctuates: it is an optimisation aid, not a guarantee."),
  ("Normalizarea pe loturi", f"Într-un MLP cu 6 straturi antrenat cu SGD la $\\eta=0{{,}}1$, {R('bn.plain_01.diverged', 'd')} din 3 inițializări diverg fără normalizare pe loturi, iar cu ea cea mai bună MSE pe validare este {R('bn.bn_01.val_best', '.3f')}. Ce aduce în principal normalizarea pe loturi?",
   ["O antrenare stabilă la rate de învățare mai mari, prin preactivări centrate și scalate", "O eroare pe test garantat mai mică", "Mai puțini parametri", "Un înlocuitor al setului de validare"],
   "Normalizarea fiecărui neuron pe mini-lot netezește suprafața pierderii (Ioffe și Szegedy, 2015); efectul de regularizare este un cîștig secundar.",
   "În acest experiment, normalizarea pe loturi a făcut posibilă antrenarea la rata mare, dar eroarea finală de validare fluctuează: este un ajutor pentru optimizare, nu o garanție."))
q(1, ("Hold-out noise", f"Over 200 random 70/30 splits of German credit, the test AUC of the same logistic model ranges from {E('holdout.min', '.3f')} to {E('holdout.max', '.3f')}. What follows?",
      ["Logistic regression is unstable", "A single small hold-out cannot tell apart models that differ by a few AUC points; use repeated cross-validation",
       "The data are wrong", "AUC should not be used"],
      f"90 % of the splits fall between {E('holdout.p05', '.3f')} and {E('holdout.p95', '.3f')}: that spread comes only from which applicants land in the test set.",
      "The model is the same in every split; only the random partition changes, which shows how noisy one small test set is."),
  ("Zgomotul unei singure împărțiri", f"Pe 200 de împărțiri aleatoare 70/30 ale datelor German credit, AUC pe test a aceluiași model logistic variază între {R('holdout.min', '.3f')} și {R('holdout.max', '.3f')}. Ce rezultă?",
   ["Regresia logistică este instabilă", "Un singur set de test mic nu poate separa modele care diferă cu cîteva puncte de AUC; folosiți validarea încrucișată repetată",
    "Datele sînt greșite", "AUC nu trebuie folosită"],
   f"90 % dintre împărțiri dau valori între {R('holdout.p05', '.3f')} și {R('holdout.p95', '.3f')}: variația vine doar din solicitanții care ajung în setul de test.",
   "Modelul este același la fiecare împărțire; se schimbă doar partiția aleatoare, ceea ce arată cît de zgomotos este un set de test mic."))
q(2, ("Nested cross-validation", "What does nested cross-validation measure?",
      ["The best hyperparameters only", "The variance of the data", "The performance of the whole procedure, including hyperparameter tuning, on data the tuning never saw",
       "The training error"],
      "The inner loop chooses hyperparameters, the outer loop evaluates the chosen model on held-out folds, so the estimate is not biased by the tuning.",
      "Reporting the best inner-loop score would reuse the data that chose the hyperparameters and overstate performance."),
  ("Validarea încrucișată imbricată", "Ce măsoară validarea încrucișată imbricată?",
   ["Doar cei mai buni hiperparametri", "Varianța datelor", "Performanța întregii proceduri, inclusiv ajustarea hiperparametrilor, pe date pe care ajustarea nu le-a văzut",
    "Eroarea de antrenare"],
   "Bucla interioară alege hiperparametrii, bucla exterioară evaluează modelul ales pe pliuri păstrate deoparte, deci estimarea nu este influențată de ajustare.",
   "Raportarea celui mai bun scor din bucla interioară ar refolosi datele care au ales hiperparametrii și ar exagera performanța."))
q(3, ("Oversampling leakage", f"Copying every fraud 20 times before a random split raises the estimated PR-AUC to {E('design.oversample_first.ap', '.3f')}, against {E('design.time.ap', '.3f')} with a time-ordered split. Why?",
      ["Oversampling improves the model", "There are more frauds in the test set", "PR-AUC is not defined after oversampling",
       "Copies of the same fraud land in both training and test sets, so the model is tested on frauds it has memorised"],
      "Resampling must happen inside the training part only; otherwise the test set shares records with the training set.",
      "The model is not better; the estimate is contaminated because the evaluation contains duplicates of training rows."),
  ("Scurgerea prin supraeșantionare", f"Copierea fiecărei fraude de 20 de ori înainte de o împărțire aleatoare crește PR-AUC estimată la {R('design.oversample_first.ap', '.3f')}, față de {R('design.time.ap', '.3f')} cu împărțire cronologică. De ce?",
   ["Supraeșantionarea îmbunătățește modelul", "În setul de test sînt mai multe fraude", "PR-AUC nu este definită după supraeșantionare",
    "Copii ale aceleiași fraude ajung și în antrenare, și în test, deci modelul este testat pe fraude memorate"],
   "Reeșantionarea trebuie făcută doar în partea de antrenare; altfel, setul de test are înregistrări comune cu cel de antrenare.",
   "Modelul nu este mai bun; estimarea este contaminată pentru că evaluarea conține duplicate ale rîndurilor de antrenare."))
q(0, ("Time-ordered split", "Why are the fraud and S&P 500 data split in time order rather than at random?",
      ["Because deployment always scores future data with a model trained on the past", "Because random splits are slower",
       "Because time-ordered splits always give higher scores", "Because random splits are not allowed in PyTorch"],
      "A random split lets the model learn from the future and mixes calm and attack periods in both sets, which overstates performance.",
      "The aim is to mimic deployment, where the model never sees later data; it is not about speed or about obtaining a higher score."),
  ("Împărțirea cronologică", "De ce sînt împărțite datele despre fraude și S&P 500 în ordine cronologică și nu aleator?",
   ["Pentru că în producție modelul antrenat pe trecut scorează întotdeauna date viitoare", "Pentru că împărțirile aleatoare sînt mai lente",
    "Pentru că împărțirile cronologice dau întotdeauna scoruri mai mari", "Pentru că împărțirile aleatoare nu sînt permise în PyTorch"],
   "O împărțire aleatoare permite modelului să învețe din viitor și amestecă perioadele liniștite și cele de atac în ambele seturi, ceea ce exagerează performanța.",
   "Scopul este să imităm producția, în care modelul nu vede niciodată date ulterioare; nu este o chestiune de viteză sau de scor mai mare."))
q(1, ("Accuracy with rare events", f"The fraud rate is {E('fraud.prev_full_pct', '.3f')} %. What accuracy does the rule 'never fraud' reach?",
      ["About 50 %", f"{100 - g('fraud.prev_full_pct'):.3f} %, while catching no fraud at all", "0 %", "Exactly the fraud rate"],
      "Accuracy counts the many correct 'legitimate' decisions; with rare events it rewards doing nothing.",
      "Precision, recall and PR-AUC focus on the rare class, which is why they are used for fraud."),
  ("Acuratețea la evenimente rare", f"Rata fraudei este {R('fraud.prev_full_pct', '.3f')} %. Ce acuratețe are regula „niciodată fraudă”?",
   ["Circa 50 %", f"{100 - g('fraud.prev_full_pct'):.3f} %, fără să detecteze nicio fraudă".replace(".", ","), "0 %", "Exact rata fraudei"],
   "Acuratețea numără multele decizii corecte „legitim”; la evenimente rare, recompensează inactivitatea.",
   "Precizia, sensibilitatea și PR-AUC se concentrează pe clasa rară, de aceea sînt folosite pentru fraudă."))
q(2, ("Precision and recall", "For a fraud alert rule with $TP$ frauds caught, $FP$ false alarms and $FN$ missed frauds, which pair is (precision, recall)?",
      ["$\\big(TP/(TP+FN),\\ TP/(TP+FP)\\big)$", "$\\big(TP/(TP+FP+FN),\\ FP/(TP+FP)\\big)$", "$\\big(TP/(TP+FP),\\ TP/(TP+FN)\\big)$", "$\\big(FP/(FP+FN),\\ FN/(TP+FN)\\big)$"],
      "Precision is the share of alerts that are frauds; recall is the share of frauds that raise an alert.",
      "Precision divides by the number of alerts, $TP+FP$; recall divides by the number of actual frauds, $TP+FN$."),
  ("Precizia și sensibilitatea", "Pentru o regulă de alertă cu $TP$ fraude detectate, $FP$ alarme false și $FN$ fraude ratate, ce pereche este (precizia, sensibilitatea)?",
   ["$\\big(TP/(TP+FN),\\ TP/(TP+FP)\\big)$", "$\\big(TP/(TP+FP+FN),\\ FP/(TP+FP)\\big)$", "$\\big(TP/(TP+FP),\\ TP/(TP+FN)\\big)$", "$\\big(FP/(FP+FN),\\ FN/(TP+FN)\\big)$"],
   "Precizia este ponderea alertelor care sînt fraude; sensibilitatea este ponderea fraudelor care declanșează o alertă.",
   "Precizia se împarte la numărul de alerte, $TP+FP$; sensibilitatea la numărul de fraude reale, $TP+FN$."))
q(3, ("Weights in precision", "The fraud file keeps all frauds and 10 % of legitimate payments. How must precision be computed to describe the real bank?",
      ["Ignore the sampling", "Drop the frauds", "Use only the legitimate payments",
       f"Count every legitimate payment with weight {E('fraud.legit_weight', '.0f')}, so false positives are counted at population scale"],
      "Each kept legitimate payment stands for ten in the full data; weighting restores the true number of false alarms.",
      "Without weights, false positives are undercounted tenfold and precision looks far better than it would be in production."),
  ("Ponderile în precizie", "Fișierul despre fraude păstrează toate fraudele și 10 % din plățile legitime. Cum trebuie calculată precizia pentru a descrie banca reală?",
   ["Ignorăm eșantionarea", "Eliminăm fraudele", "Folosim doar plățile legitime",
    f"Numărăm fiecare plată legitimă cu ponderea {R('fraud.legit_weight', '.0f')}, astfel încît fals pozitivele sînt numărate la scara populației"],
   "Fiecare plată legitimă păstrată ține locul a zece din datele complete; ponderarea reface numărul real al alarmelor false.",
   "Fără ponderi, fals pozitivele sînt subnumărate de zece ori, iar precizia pare mult mai bună decît ar fi în producție."))
q(0, ("Which regulariser helped", f"On the fraud test hours, test PR-AUC is {E('abl.none.ap', '.3f')} with no regularisation, {E('abl.es.ap', '.3f')} with early stopping and {E('abl.wd.ap', '.3f')} with weight decay alone (60 epochs, 5 seeds). What do you conclude?",
      ["Early stopping is the regulariser that clearly helps here; weight decay alone stays within the seed noise", "Weight decay is the best regulariser",
       "Regularisation never helps on fraud data", "One seed would have been enough"],
      "With a fixed 60-epoch budget the network overfits the few training frauds; stopping at the best validation epoch prevents it, the other penalties barely change the result.",
      "The comparison uses 5 seeds per configuration; differences smaller than the seed spread are not evidence."),
  ("Ce regularizator a ajutat", f"Pe orele de test ale datelor despre fraude, PR-AUC este {R('abl.none.ap', '.3f')} fără regularizare, {R('abl.es.ap', '.3f')} cu oprire timpurie și {R('abl.wd.ap', '.3f')} doar cu penalizarea ponderilor (60 de epoci, 5 inițializări). Ce concluzionați?",
   ["Oprirea timpurie este regularizatorul care ajută clar aici; penalizarea singură rămîne în zgomotul inițializărilor", "Penalizarea ponderilor este cel mai bun regularizator",
    "Regularizarea nu ajută niciodată la datele despre fraude", "O singură inițializare ar fi fost suficientă"],
   "Cu un buget fix de 60 de epoci, rețeaua memorează puținele fraude de antrenare; oprirea la epoca cea mai bună pe validare previne acest lucru, celelalte penalizări aproape că nu schimbă rezultatul.",
   "Comparația folosește 5 inițializări pe configurație; diferențele mai mici decît variația dintre inițializări nu sînt dovezi."))
q(1, ("Comparing detectors", f"Test PR-AUC is {E('final.logit.ap', '.3f')} for logistic regression, {E('final.mlp.ap', '.3f')} for the regularised MLP and {E('final.xgb.ap', '.3f')} for XGBoost, with {E('fraud.fr_test', 'd')} test frauds. How confident can we be in the ranking?",
      ["Completely: the MLP is the best detector", "Moderately: with so few test frauds, differences of a few points are within sampling noise",
       "Not at all: PR-AUC cannot compare models", "The ranking is the same as for accuracy"],
      "Each test fraud moves the curve noticeably; a bootstrap of the test hours or more data would be needed to separate close models.",
      "The point estimates are real, but their uncertainty with a few dozen events is large; report it alongside the ranking."),
  ("Compararea detectoarelor", f"PR-AUC pe test este {R('final.logit.ap', '.3f')} pentru regresia logistică, {R('final.mlp.ap', '.3f')} pentru MLP regularizat și {R('final.xgb.ap', '.3f')} pentru XGBoost, cu {R('fraud.fr_test', 'd')} de fraude în test. Cît de siguri putem fi de ordine?",
   ["Complet: MLP este cel mai bun detector", "Moderat: cu atît de puține fraude în test, diferențele de cîteva puncte sînt în zgomotul de eșantionare",
    "Deloc: PR-AUC nu poate compara modele", "Ordinea este aceeași ca pentru acuratețe"],
   "Fiecare fraudă din test mișcă vizibil curba; ar fi nevoie de un bootstrap pe orele de test sau de mai multe date pentru a separa modele apropiate.",
   "Estimările punctuale sînt reale, dar incertitudinea lor, cu cîteva zeci de evenimente, este mare; raportați-o alături de ordine."))
q(2, ("Cost of alerts", f"With a review cost of {E('cost.review', '.0f')} EUR per alert and missed frauds losing their amount, the test losses fall from {E('cost.no_model', ',.0f')} EUR with no alerts to {E('cost.mlp.min', ',.0f')} EUR for the MLP at its best alert count. What sets that count?",
      ["The PR-AUC alone", "The number of frauds in training", "The trade-off between review costs and the amounts of the frauds caught", "The 0.5 cut-off"],
      "Each extra alert costs a review and may catch a fraud; the optimum is where the marginal fraud amount saved equals the review cost.",
      "A fixed 0.5 cut-off ignores costs; the alert budget is a business decision computed from amounts and review costs."),
  ("Costul alertelor", f"Cu un cost de verificare de {R('cost.review', '.0f')} EUR pe alertă și fraudele ratate pierzîndu-și suma, pierderile pe test scad de la {R('cost.no_model', ',.0f')} EUR fără alerte la {R('cost.mlp.min', ',.0f')} EUR pentru MLP, la numărul optim de alerte. Ce stabilește acest număr?",
   ["Doar PR-AUC", "Numărul de fraude din antrenare", "Echilibrul dintre costul verificărilor și sumele fraudelor detectate", "Pragul de 0,5"],
   "Fiecare alertă în plus costă o verificare și poate prinde o fraudă; optimul este acolo unde suma marginală salvată egalează costul verificării.",
   "Un prag fix de 0,5 ignoră costurile; bugetul de alerte este o decizie de afaceri calculată din sume și costuri de verificare."))
q(3, ("Prior correction", "A model is trained on data where legitimate payments were kept with rate $\\beta=0.1$. How are its probabilities $p_s$ corrected?",
      ["$p=p_s/\\beta$", "$p=\\beta p_s$", "No correction is needed", "$p=\\beta p_s/(\\beta p_s-p_s+1)$"],
      "Undersampling the negative class inflates the odds by $1/\\beta$; Dal Pozzolo et al. (2015) give the exact correction.",
      "Simple rescalings do not keep $p$ in $[0,1]$ or do not undo the change in the odds; the ranking is unchanged, only the levels move."),
  ("Corecția pentru distribuția a priori", "Un model este antrenat pe date în care plățile legitime au fost păstrate cu rata $\\beta=0{,}1$. Cum se corectează probabilitățile lui $p_s$?",
   ["$p=p_s/\\beta$", "$p=\\beta p_s$", "Nu este nevoie de corecție", "$p=\\beta p_s/(\\beta p_s-p_s+1)$"],
   "Subeșantionarea clasei negative umflă șansa cu $1/\\beta$; Dal Pozzolo et al. (2015) dau corecția exactă.",
   "Rescalările simple nu păstrează $p$ în $[0,1]$ sau nu anulează schimbarea șansei; ordonarea rămîne aceeași, se schimbă doar nivelurile."))
q(0, ("Data augmentation", "Why is data augmentation common for images but rarely safe for tabular credit data?",
      ["For images, crops and flips keep the label; for a credit file there is rarely a transformation that provably keeps the default label",
       "Tabular data are too large", "Augmentation only works with convolutions", "Credit data have no labels"],
      "A flipped photo of a cat is still a cat; changing an applicant's income or arrears may change their true risk.",
      "Augmentation is valid only with label-preserving transformations; that is a property of the domain, not of the model."),
  ("Augmentarea datelor", "De ce este augmentarea datelor obișnuită pentru imagini, dar rareori sigură pentru datele tabelare de credit?",
   ["La imagini, decupările și oglindirile păstrează eticheta; pentru un dosar de credit rareori există o transformare care păstrează sigur eticheta de neplată",
    "Datele tabelare sînt prea mari", "Augmentarea funcționează doar cu convoluții", "Datele de credit nu au etichete"],
   "O fotografie oglindită a unei pisici rămîne o pisică; modificarea venitului sau a restanțelor unui solicitant îi poate schimba riscul real.",
   "Augmentarea este validă doar cu transformări care păstrează eticheta; aceasta este o proprietate a domeniului, nu a modelului."))
q(1, ("Ensembles", "Why does averaging the predictions of 5 seeds usually help?",
      ["It uses more data", "It reduces the variance of the prediction, roughly by $1/M$ for $M$ weakly correlated members", "It removes bias", "It changes the loss function"],
      "Different seeds reach different solutions; their errors partly cancel in the average, which is a cheap form of regularisation.",
      "Averaging does not add information or reduce bias; it lowers the variance part of the error."),
  ("Ansamblurile", "De ce ajută de obicei media predicțiilor a 5 inițializări?",
   ["Folosește mai multe date", "Reduce varianța predicției, aproximativ cu $1/M$ pentru $M$ membri slab corelați", "Elimină deplasarea", "Schimbă funcția de pierdere"],
   "Inițializările diferite ajung la soluții diferite; erorile lor se compensează parțial în medie, ceea ce este o formă ieftină de regularizare.",
   "Media nu adaugă informație și nu reduce deplasarea; scade componenta de varianță a erorii."))
q(2, ("Leakage through preprocessing", "Which step leaks test information into training?",
      ["Fitting the scaler on the training rows", "Stratifying the split by the label", "Imputing missing values with medians computed on all rows before splitting",
       "Using a time-ordered split"],
      "Statistics computed on all rows contain the evaluation rows; every fitted preprocessing step belongs inside the training part.",
      "Stratifying and time-ordered splits are legitimate design choices; the leak comes from statistics that use evaluation rows."),
  ("Scurgerea prin preprocesare", "Ce pas scurge informație din setul de test în antrenare?",
   ["Estimarea standardizării pe rîndurile de antrenare", "Stratificarea împărțirii după etichetă", "Completarea valorilor lipsă cu mediane calculate pe toate rîndurile înainte de împărțire",
    "Folosirea unei împărțiri cronologice"],
   "Statisticile calculate pe toate rîndurile conțin rîndurile de evaluare; orice pas de preprocesare estimat aparține părții de antrenare.",
   "Stratificarea și împărțirea cronologică sînt alegeri legitime de proiectare; scurgerea vine din statistici care folosesc rînduri de evaluare."))
q(3, ("Target leakage", "A default model uses 'days past due at month 12' as an input. What is wrong?",
      ["Nothing, it is a strong predictor", "It should be standardised", "It needs a missing-value indicator",
       "It is not known at the time of the credit decision, so the model would use information from the future"],
      "Inputs must be available at decision time; a variable recorded after the outcome makes the test score look excellent and fails in production.",
      "The problem is not scaling or missingness; it is that the input contains the outcome the model is supposed to predict."),
  ("Scurgerea țintei", "Un model de neplată folosește ca intrare „zile de întîrziere în luna 12”. Ce este greșit?",
   ["Nimic, este un predictor puternic", "Trebuie standardizată", "Are nevoie de un indicator de valoare lipsă",
    "Nu este cunoscută în momentul deciziei de creditare, deci modelul ar folosi informații din viitor"],
   "Intrările trebuie să fie disponibile la momentul deciziei; o variabilă înregistrată după rezultat face scorul pe test excelent și eșuează în producție.",
   "Problema nu este scalarea sau lipsa valorilor; intrarea conține chiar rezultatul pe care modelul ar trebui să-l prezică."))

